#!/usr/bin/env python3
"""Apply UUID companion field edits to generated Elixir client."""
from __future__ import annotations

import re
from pathlib import Path

ROOT = Path("out/manticoresearch-elixir")

DOCUMENT_ID = """# NOTE: This file is auto generated by OpenAPI Generator 7.17.0 (https://openapi-generator.tech).
# Do not edit this file manually.

defmodule Manticoresearch.DocumentId do
  @moduledoc false

  @spec split(term()) :: {integer() | nil, String.t() | nil}
  def split(nil), do: {nil, nil}
  def split(id) when is_integer(id), do: {id, nil}
  def split(id) when is_binary(id), do: {nil, id}
  def split(id) when is_float(id), do: {trunc(id), nil}

  @spec wire_value(integer() | nil, String.t() | nil) :: integer() | String.t() | nil
  def wire_value(_id, uuid) when is_binary(uuid), do: uuid
  def wire_value(id, _uuid) when is_integer(id), do: id
  def wire_value(id, _uuid) when is_float(id), do: trunc(id)
  def wire_value(_id, _uuid), do: nil
end
"""

MODELS = [
    ("delete_document_request.ex", "id"),
    ("delete_response.ex", "id"),
    ("insert_document_request.ex", "id"),
    ("success_response.ex", "id"),
    ("update_document_request.ex", "id"),
    ("update_response.ex", "id"),
    ("hits_hits.ex", "_id"),
    ("knn.ex", "doc_id"),
]

SPLIT_WIRE = """
  defp split_wire_id(value, wire_key) when is_map(value) do
    case Map.get(value, wire_key) do
      id when is_binary(id) ->
        value
        |> Map.put(:uuid, id)
        |> Map.put(wire_key, nil)

      _ ->
        value
    end
  end

  defp split_wire_id(value, _), do: value
"""

ENCODER_IMPL = """
defimpl JSON.Encoder, for: {module} do
  def encode(struct, opts) do
    struct
    |> Map.from_struct()
    |> put_wire_id({wire})
    |> Map.drop([:uuid])
    |> then(&JSON.Encoder.Map.encode(&1, opts))
  end

  defp put_wire_id(map, wire_key) do
    wire = Manticoresearch.DocumentId.wire_value(Map.get(map, wire_key), Map.get(map, :uuid))

    map
    |> then(fn m ->
      if wire, do: Map.put(m, wire_key, wire), else: Map.delete(m, wire_key)
    end)
  end
end
"""


def module_name(filename: str) -> str:
    base = filename.replace(".ex", "")
    return "Manticoresearch.Model." + "".join(part.capitalize() for part in base.split("_"))


def patch_model(filename: str, wire_key: str) -> None:
    path = ROOT / "lib/manticoresearch/model" / filename
    text = path.read_text()
    module = module_name(filename)
    wire_atom = f":{wire_key}"

    if ":uuid" in text:
        return

    text = text.replace("  @derive JSON.Encoder\n", "")
    text = text.replace(
        f"    {wire_atom},\n",
        f"    {wire_atom},\n    :uuid,\n",
        1,
    )
    text = text.replace(
        f"    {wire_atom} => integer() | nil,\n",
        f"    {wire_atom} => integer() | nil,\n    :uuid => String.t | nil,\n",
        1,
    )

    decode_match = re.search(r"  def decode\(value\) do\n(.*?)  end\nend\n", text, re.S)
    if not decode_match:
        raise SystemExit(f"decode block not found in {filename}")

    decode_body = decode_match.group(1)
    if "split_wire_id" not in decode_body:
        if decode_body.strip() == "value":
            new_body = f"    split_wire_id(value, {wire_atom})\n"
        else:
            new_body = f"    value\n    |> split_wire_id({wire_atom}){decode_body[len('    value'):]}"
        text = text.replace(
            decode_match.group(0),
            f"  def decode(value) do\n{new_body}  end{SPLIT_WIRE}\nend\n",
            1,
        )

    encoder = ENCODER_IMPL.format(module=module, wire=wire_atom)
    if f"defimpl JSON.Encoder, for: {module}" not in text:
        text = text.rstrip() + "\n" + encoder + "\n"

    path.write_text(text)


def patch_index() -> None:
    path = ROOT / "lib/manticoresearch/api/index.ex"
    text = path.read_text()
    if "partial_replace_uuid" in text:
        return

    marker = "  def partial_replace(connection, table, id, replace_document_request, _opts \\\\ []) do"
    insert = """  @spec partial_replace_uuid(Tesla.Env.client(), String.t(), String.t(), Manticoresearch.Model.ReplaceDocumentRequest.t(), keyword()) :: {:ok, Manticoresearch.Model.UpdateResponse.t} | {:ok, Manticoresearch.Model.ErrorResponse.t} | {:error, Tesla.Env.t}
  def partial_replace_uuid(connection, table, uuid, replace_document_request, opts \\\\ []) do
    partial_replace(connection, table, uuid, replace_document_request, opts)
  end

"""
    if marker not in text:
        raise SystemExit("failed to locate partial_replace in index.ex")
    text = text.replace(marker, insert + marker, 1)
    path.write_text(text)


def main() -> None:
    (ROOT / "lib/manticoresearch/document_id.ex").write_text(DOCUMENT_ID)

    for filename, wire_key in MODELS:
        patch_model(filename, wire_key)

    patch_index()
    print("Applied Elixir UUID companion field edits.")


if __name__ == "__main__":
    main()
